-- Encrypted per-role session store (SESSION-004; CONTEXT_PACK §3.1, §8.1, §8.6, §8.7). Generated by `pnpm db:generate
-- --name role_sessions_store` from src/schema/role-sessions.ts, then reviewed. Forward-only: never edit once applied.
-- One row per (tenant, run, asset, role). enc_material is the envelope ciphertext only; revoked and expired rows keep
-- their metadata and lose their material. Composite (tenant_id, …) foreign keys stop a session naming another tenant.
CREATE TABLE "role_sessions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"run_id" uuid NOT NULL,
	"asset_id" uuid NOT NULL,
	"role_name" text NOT NULL,
	"kind" text NOT NULL,
	"enc_material" "bytea" NOT NULL,
	"enc_key_ref" text NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"last_validated_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "role_sessions_scope_key" UNIQUE("tenant_id","run_id","asset_id","role_name"),
	CONSTRAINT "role_sessions_role_name_check" CHECK ("role_sessions"."role_name" ~ '^[A-Za-z0-9_.-]{1,64}$'),
	CONSTRAINT "role_sessions_kind_check" CHECK ("role_sessions"."kind" IN ('cookie', 'bearer', 'header', 'storage')),
	CONSTRAINT "role_sessions_status_check" CHECK ("role_sessions"."status" IN ('active', 'expired', 'revoked', 'refreshing')),
	CONSTRAINT "role_sessions_material_check" CHECK (("role_sessions"."status" IN ('expired', 'revoked')) OR octet_length("role_sessions"."enc_material") > 0),
	CONSTRAINT "role_sessions_material_max_check" CHECK (octet_length("role_sessions"."enc_material") <= 131072)
);
