ALTER TABLE "role_sessions" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
-- The runtime role reads, stores and updates sessions. It never deletes or truncates a row: a revoked or expired session
-- keeps its audit metadata and loses its material (UPDATE), so there is no DELETE path to the store.
